} else {
  warpCooldown = 0;
  boostLeft = 0;
}

  // v1.0.0 Build 10: allow all Active Actors (Human AI & Wolf AI) to use WarpPad & SpeedPad
  const warpsAll = runtimeScene.getObjects('WarpPad');
  const speedPadsAll = runtimeScene.getObjects('SpeedPad');
  for (const actor of runtimeScene.getObjects('Actor')) {
