    if (actor.__iceWolfV068WarpCooldown <= 0 && warpsAll.length >= 2) {
      let src = null;
      for (const wpad of warpsAll) {
        if (insidePad(wpad, acx, acy, 0)) { src = wpad; break; }
      }
      if (src) {
        let dst = null;
        for (const wpad of warpsAll) {
          if (wpad !== src) { dst = wpad; break; }
        }
        if (dst) {
          actor.setX(dst.getX() + dst.getWidth() / 2 - actor.getWidth() / 2);
          actor.setY(dst.getY() + dst.getHeight() / 2 - actor.getHeight() / 2);
          if (typeof actor.setZ === 'function') actor.setZ(0);
