runtimeScene.__iceWolfV068OnSpeedPad = playing ? onSpeedPad : false;
vars.get('SpeedBoostLeft').setNumber(boostLeft);
vars.get('WarpCooldownLeft').setNumber(warpCooldown);
vars.get('OnSpeedPad').setBoolean(playing && onSpeedPad);
vars.get('SpeedFactor').setNumber(boostLeft > 0 ? vars.get('SpeedBoostFactor').getAsNumber() : 1);

const dt = gdjs.evtTools.runtimeScene.getElapsedTimeInSeconds(runtimeScene);
const vars = runtimeScene.getVariables();
const gameOver = vars.get('GameOver').getAsBoolean();
if (!gameOver) {
  const players = runtimeScene.getObjects('Player');
  const player = players.length ? players[0] : null;
  if (player) {
    const pVars = player.getVariables();
    const pRole = pVars.get('Role').getAsString();
    const pState = pVars.get('State').getAsString();
    const playerWolfModeLeft = vars.get('WolfModeLeft').getAsNumber();
    const px = player.getCenterXInScene();
    const py = player.getCenterYInScene();
    const actors = runtimeScene.getObjects('Actor');
    const fleeRadius = 360;
    const fleeSpeed = 155;
    const wanderSpeed = 65;
    const rescueSearchRadius = 520;
    const rescueSpeed = 95;
    const rescueDistance = 34;
    const rescueDangerRadius = 360;
    const aiWolfTriggerRadius = 420;
    const aiWolfModeDuration = 5;
    const aiWolfCooldownDuration = 5;
    const aiWolfChaseSpeed = 205;
    const aiWolfStalkSpeed = 90;
    const aiWolfWanderSpeed = 65;
    const aiWolfFreezeDistance = 30;
    // v0.7.2: the shared stair rules. The pads and the warp stay v0.7.0's.
    const FLOOR_GAP_X = 792;
    const AI_WOLF_PREY_SEARCH = 1.6;
    const AI_HUMAN_STAIR_FLEE_RADIUS = 300;
    const AI_WOLF_TRAVEL_SPEED = 150;
    const aiFloorOf = (centerX) => (centerX > FLOOR_GAP_X ? '2F' : '1F');
    const aiCanCross = (rider) => (typeof runtimeScene.__iceWolfV072CanCross === 'function' ? runtimeScene.__iceWolfV072CanCross(rider) : false);
    const aiStairToward = (rider, targetCenterX) => (typeof runtimeScene.__iceWolfV070StairToward === 'function' ? runtimeScene.__iceWolfV070StairToward(rider, targetCenterX) : null);
    const aiStairAway = (rider, threatX) => (typeof runtimeScene.__iceWolfV072StairAway === 'function' ? runtimeScene.__iceWolfV072StairAway(rider, threatX) : null);
    // v0.7.4: one wall-aware, path-following steering step for both roles, plus the
    // goal it should walk to when there is one (see the block above).
    const aiSteer = (mover, vx, vy, speed, goalX, goalY) => (typeof runtimeScene.__iceWolfV074Steer === 'function'
      ? runtimeScene.__iceWolfV074Steer(mover, vx, vy, speed, goalX, goalY)
      : { x: vx, y: vy });

    const activeHumanTargets = (wolfActor) => {
      const targets = [];
      if (pRole === 'Human' && pState === 'Active') targets.push(player);
      for (const candidate of actors) {
        if (candidate === wolfActor) continue;
        const cv = candidate.getVariables();
        if (cv.get('Role').getAsString() === 'Human' && cv.get('State').getAsString() === 'Active') targets.push(candidate);
      }
      return targets;
    };

    // Pass 1: every Active Actor Wolf stays a Wolf for the rest of the match.
    // Outside WOLF MODE it stalks while disguised as a white Human; after cooldown
    // it re-enters WOLF MODE, chases, freezes one Human, cools down, and repeats.
    // It can never INFECT.
    for (const wolf of actors) {
      const wv = wolf.getVariables();
      if (wv.get('Role').getAsString() !== 'Wolf' || wv.get('State').getAsString() !== 'Active') continue;
      let modeLeft = Math.max(0, wv.get('AIWolfModeLeft').getAsNumber() - dt);
      let cooldownLeft = Math.max(0, wv.get('AIWolfCooldownLeft').getAsNumber() - dt);
      wv.get('AIWolfModeLeft').setNumber(modeLeft);
      wv.get('AIWolfCooldownLeft').setNumber(cooldownLeft);
      wolf.__iceWolfDiagnosticHoldLeft = Math.max(0, (Number.isFinite(wolf.__iceWolfDiagnosticHoldLeft) ? wolf.__iceWolfDiagnosticHoldLeft : 0) - dt);
      if (wolf.__iceWolfDiagnosticHoldLeft > 0) {
        continue;
      }
      const wx = wolf.getCenterXInScene();
      const wy = wolf.getCenterYInScene();
      let target = null;
      let targetDist = Infinity;
      let otherFloorTarget = null;
      let otherFloorDist = Infinity;
      const wolfFloor = aiFloorOf(wx);
      const diagPhase = vars.get('CpuWolfDiagPhase').getAsNumber();
      const forceDiagnosticPlayerTarget = wolf.__iceWolfDiagnosticTargetPlayer === true && diagPhase === 1 && pRole === 'Human' && pState === 'Active';
      if (forceDiagnosticPlayerTarget) {
        target = player;
        targetDist = Math.hypot(player.getCenterXInScene() - wx, player.getCenterYInScene() - wy);
      } else {
        // v0.7.2: hunt what is on this floor. A Human on the other floor is only a
        // reason to ride the stairs, never a reason to grind along the border.
        for (const human of activeHumanTargets(wolf)) {
          const hx = human.getCenterXInScene();
          const d = Math.hypot(hx - wx, human.getCenterYInScene() - wy);
          if (aiFloorOf(hx) === wolfFloor) {
            if (d < targetDist) { target = human; targetDist = d; }
          } else if (d < otherFloorDist) {
            otherFloorTarget = human;
            otherFloorDist = d;
          }
        }
      }
      if (target) {
        wolf.__iceWolfV072NoPreyFor = 0;
      } else {
        wolf.__iceWolfV072NoPreyFor = (Number.isFinite(wolf.__iceWolfV072NoPreyFor) ? wolf.__iceWolfV072NoPreyFor : 0) + dt;
      }
      if (modeLeft <= 0 && cooldownLeft <= 0 && target && targetDist <= aiWolfTriggerRadius) {
        modeLeft = aiWolfModeDuration;
        wv.get('AIWolfModeLeft').setNumber(modeLeft);
      }
      let vx = 0;
      let vy = 0;
      let speed = aiWolfWanderSpeed;
      let goalX = NaN;
      let goalY = NaN;
      if (modeLeft > 0 && target) {
        const tdx = target.getCenterXInScene() - wx;
        const tdy = target.getCenterYInScene() - wy;
        const td = Math.max(Math.hypot(tdx, tdy), 1);
        goalX = target.getCenterXInScene();
        goalY = target.getCenterYInScene();
        vx = tdx / td;
        vy = tdy / td;
        speed = aiWolfChaseSpeed;
        wolf.__iceWolfAIWolfTurnLeft = 0;
        if (targetDist <= aiWolfFreezeDistance) {
          const diagnosticPlayerFreeze = wolf.__iceWolfDiagnosticTargetPlayer === true && vars.get('CpuWolfDiagPhase').getAsNumber() === 1 && target === player;
          target.getVariables().get('State').setString('Frozen');
          wv.get('AIWolfModeLeft').setNumber(0);
          wv.get('AIWolfCooldownLeft').setNumber(diagnosticPlayerFreeze ? 30 : aiWolfCooldownDuration);
          if (diagnosticPlayerFreeze) {
            vars.get('CpuWolfDiagPhase').setNumber(2);
            wolf.__iceWolfDiagnosticTargetPlayer = false;
            wolf.__iceWolfDiagnosticHoldLeft = 8;
            wolf.setX(-620);
            wolf.setY(-620);
            const rescuer = actors.find(candidate => candidate !== wolf && candidate.getVariables().get('Role').getAsString() === 'Human' && candidate.getVariables().get('State').getAsString() === 'Active');
            if (rescuer) {
              rescuer.setX(player.getCenterXInScene() + 90);
              rescuer.setY(player.getCenterYInScene());
              rescuer.__iceWolfAIRescueCooldown = 0;
              rescuer.__iceWolfAITurnLeft = 0;
            }
          }
          continue;
        }
      } else if (target) {
        // Hidden stalking: the awakened Wolf remains visually white outside
        // WOLF MODE, but keeps closing the distance instead of wandering away.
        const sdx = target.getCenterXInScene() - wx;
        const sdy = target.getCenterYInScene() - wy;
        const sd = Math.max(Math.hypot(sdx, sdy), 1);
        goalX = target.getCenterXInScene();
        goalY = target.getCenterYInScene();
        vx = sdx / sd;
        vy = sdy / sd;
        speed = aiWolfStalkSpeed;
        wolf.__iceWolfAIWolfTurnLeft = 0;
      } else {
        if (!Number.isFinite(wolf.__iceWolfAIWolfTurnLeft) || wolf.__iceWolfAIWolfTurnLeft <= 0 || !Number.isFinite(wolf.__iceWolfAIWolfDirX) || !Number.isFinite(wolf.__iceWolfAIWolfDirY)) {
          const angle = Math.random() * Math.PI * 2;
          wolf.__iceWolfAIWolfDirX = Math.cos(angle);
          wolf.__iceWolfAIWolfDirY = Math.sin(angle);
          wolf.__iceWolfAIWolfTurnLeft = 0.65 + Math.random() * 0.9;
        }
        wolf.__iceWolfAIWolfTurnLeft -= dt;
        vx = wolf.__iceWolfAIWolfDirX;
        vy = wolf.__iceWolfAIWolfDirY;
      }
      // v0.7.2: after a ride the Wolf sweeps the floor it arrived on before it may
      // cross again, so the floors are patrolled instead of ping-ponged.
      if (Number.isFinite(wolf.__iceWolfV072PatrolLeft) && wolf.__iceWolfV072PatrolLeft > 0) {
        wolf.__iceWolfV072PatrolLeft -= dt;
        if (!target) {
          const roomCenterX = wolfFloor === '2F' ? 1592 : -8;
          goalX = roomCenterX;
          goalY = 0;
          const pdx = roomCenterX - wx;
          const pdy = -wy;
          const pdd = Math.hypot(pdx, pdy);
          if (pdd > 90) {
            vx = pdx / pdd;
            vy = pdy / pdd;
            speed = aiWolfWanderSpeed;
            wolf.__iceWolfAIWolfTurnLeft = 0;
          }
        }
      }
      // v0.7.2: nothing left to chase on this floor for a moment -> ride the same
      // stair pad the player uses and hunt the other floor. Applied last so the wall
      // detour cannot steer it away from a crossing it already committed to.
      wolf.__iceWolfV072SameFloorTime = (wolf.__iceWolfV072LastHuntFloor === wolfFloor) ? ((wolf.__iceWolfV072SameFloorTime || 0) + dt) : 0;
      wolf.__iceWolfV072LastHuntFloor = wolfFloor;
      const wolfStairCommit = wolf.__iceWolfV072StairTarget;
      if (wolf.__iceWolfV072StairBound === true && wolfStairCommit && Number.isFinite(wolfStairCommit.x) && Number.isFinite(wolfStairCommit.y)) {
        const wcdx = wolfStairCommit.x - wx;
        const wcdy = wolfStairCommit.y - wy;
        const wcdd = Math.hypot(wcdx, wcdy);
        if (wcdd > 2) {
          vx = wcdx / Math.max(wcdd, 1);
          vy = wcdy / Math.max(wcdd, 1);
          goalX = wolfStairCommit.x;
          goalY = wolfStairCommit.y;
          speed = AI_WOLF_TRAVEL_SPEED;
        }
      }
      if (otherFloorTarget && (!target || (targetDist > 520 && wolf.__iceWolfV072SameFloorTime >= 9.0)) && (wolf.__iceWolfV072FloorLockLeft || 0) <= 0 && (wolf.__iceWolfV072NoPreyFor >= AI_WOLF_PREY_SEARCH || wolf.__iceWolfV072SameFloorTime >= 9.0) && aiCanCross(wolf)) {
        const hop = aiStairToward(wolf, otherFloorTarget.getCenterXInScene());
        if (hop) {
          vx = hop.vx;
          vy = hop.vy;
          goalX = hop.tx;
          goalY = hop.ty;
          speed = AI_WOLF_TRAVEL_SPEED;
          wolf.__iceWolfV072StairBound = true;
          wolf.__iceWolfV072BoundLeft = 6;
          wolf.__iceWolfV072StairTarget = { x: hop.tx, y: hop.ty };
          wolf.__iceWolfV072SameFloorTime = 0;
        }
      }
      // v0.7.4: walk the path around the wall instead of pressing into it.
      if ((wolf.__iceWolfV068SpeedBoostLeft || 0) > 0) speed *= 1.35;
      if (speed > 0) {
        const steered = aiSteer(wolf, vx, vy, speed, goalX, goalY);
        vx = steered.x;
        vy = steered.y;
      }
      // v0.7.0: each floor clamps on its own rectangle, so a wolf that rode the stairs
      // keeps patrolling 2F instead of being pulled back to the 1F border.
      const wolfNextX = wolf.getX() + vx * speed * dt;
      const wolfNextY = wolf.getY() + vy * speed * dt;
      const wolfOnSecondFloor = (wolf.getX() + wolf.getWidth() / 2) > 792;
      wolf.setX(Math.max(wolfOnSecondFloor ? 892 : -708, Math.min(wolfOnSecondFloor ? 2292 : 692, wolfNextX)));
      wolf.setY(Math.max(-708, Math.min(692, wolfNextY)));
    }

    const visibleWolfThreat = (x, y) => {
      let threat = null;
      let best = Infinity;
      if (pRole === 'Wolf' && pState === 'Active' && playerWolfModeLeft > 0) {
        const d = Math.hypot(px - x, py - y);
        if (d < best) { best = d; threat = { x: px, y: py, dist: d }; }
      }
      for (const candidate of actors) {
        const cv = candidate.getVariables();
        if (cv.get('Role').getAsString() !== 'Wolf' || cv.get('State').getAsString() !== 'Active' || cv.get('AIWolfModeLeft').getAsNumber() <= 0) continue;
        const cx = candidate.getCenterXInScene();
        const cy = candidate.getCenterYInScene();
        const d = Math.hypot(cx - x, cy - y);
        if (d < best) { best = d; threat = { x: cx, y: cy, dist: d }; }
      }
      return threat;
    };

    // Pass 2: Human wander/flee/rescue AI. Any visible Wolf (Player or awakened
    // Actor Wolf) is treated as a threat only while that Wolf is in WOLF MODE.
    for (const actor of actors) {
      const actorVars = actor.getVariables();
      const role = actorVars.get('Role').getAsString();
      const state = actorVars.get('State').getAsString();
      if (role !== 'Human' || state !== 'Active') continue;
      actorVars.get('AIWolfModeLeft').setNumber(0);
      actor.__iceWolfAIRescueCooldown = Math.max(0, (Number.isFinite(actor.__iceWolfAIRescueCooldown) ? actor.__iceWolfAIRescueCooldown : 0) - dt);
      const ax = actor.getCenterXInScene();
      const ay = actor.getCenterYInScene();
      const humanFloor = aiFloorOf(ax);
      let vx = 0;
      let vy = 0;
      let speed = wanderSpeed;
      let hasIntent = false;
      let goalX = NaN;
      let goalY = NaN;
      // v0.7.2: a Human that chose a stair keeps walking to that pad until it rides,
      // the bound expires or the round ends - it does not re-plan every frame.
      const stairCommit = actor.__iceWolfV072StairTarget;
      if (actor.__iceWolfV072StairBound === true && stairCommit && Number.isFinite(stairCommit.x) && Number.isFinite(stairCommit.y)) {
        const cdx = stairCommit.x - ax;
        const cdy = stairCommit.y - ay;
        const cdd = Math.hypot(cdx, cdy);
        if (cdd > 2) {
          vx = cdx / Math.max(cdd, 1);
          vy = cdy / Math.max(cdd, 1);
          speed = actor.__iceWolfV072StairPace === 'rescue' ? rescueSpeed : fleeSpeed;
          hasIntent = true;
          actor.__iceWolfAITurnLeft = 0;
          goalX = stairCommit.x;
          goalY = stairCommit.y;
        }
      }
      const threat = visibleWolfThreat(ax, ay);
      if (!hasIntent && threat && threat.dist < fleeRadius) {
        const safeDist = Math.max(threat.dist, 1);
        vx = (ax - threat.x) / safeDist;
        vy = (ay - threat.y) / safeDist;
        speed = fleeSpeed;
        hasIntent = true;
        actor.__iceWolfAITurnLeft = 0;
        // v0.7.2: a Wolf inside the danger ring on this floor turns the stairs into
        // an escape route. The start delay and the two-rider limit spread the group.
        if (threat.dist < AI_HUMAN_STAIR_FLEE_RADIUS && aiFloorOf(threat.x) === humanFloor && aiCanCross(actor)) {
          const escape = aiStairAway(actor, threat.x);
          if (escape) {
            vx = escape.vx;
            vy = escape.vy;
            speed = fleeSpeed;
            actor.__iceWolfV072StairBound = true;
            actor.__iceWolfV072BoundLeft = 6;
            actor.__iceWolfV072StairPace = 'flee';
            actor.__iceWolfV072StairTarget = { x: ax + escape.vx * escape.distance, y: ay + escape.vy * escape.distance };
            goalX = actor.__iceWolfV072StairTarget.x;
            goalY = actor.__iceWolfV072StairTarget.y;
          }
        }
      } else if (!hasIntent && actor.__iceWolfAIRescueCooldown <= 0) {
        let rescueTarget = null;
        let rescueTargetDist = Infinity;
        const playerStateNow = pVars.get('State').getAsString();
        if (pRole === 'Human' && playerStateNow === 'Frozen') {
          const pd = Math.hypot(px - ax, py - ay);
          if (pd <= rescueSearchRadius) {
            rescueTarget = player;
            rescueTargetDist = pd;
          }
        }
        for (const target of actors) {
          if (target === actor) continue;
          const targetState = target.getVariables().get('State').getAsString();
          if (targetState !== 'Frozen' && targetState !== 'FrozenWolfCandidate') continue;
          const tx = target.getCenterXInScene();
          const ty = target.getCenterYInScene();
          const td = Math.hypot(tx - ax, ty - ay);
          if (td < rescueTargetDist && td <= rescueSearchRadius) { rescueTarget = target; rescueTargetDist = td; }
        }
        if (rescueTarget) {
          const tx = rescueTarget.getCenterXInScene();
          const ty = rescueTarget.getCenterYInScene();
          const targetThreat = visibleWolfThreat(tx, ty);
          const targetDanger = targetThreat && targetThreat.dist < rescueDangerRadius;
          if (!targetDanger) {
            // v0.7.2: an ally frozen on the other floor is a stair crossing.
            if (aiFloorOf(tx) !== humanFloor) {
              if (aiCanCross(actor)) {
                const rescueHop = aiStairToward(actor, tx);
                if (rescueHop) {
                  vx = rescueHop.vx;
                  vy = rescueHop.vy;
                  speed = rescueSpeed;
                  hasIntent = true;
                  actor.__iceWolfAITurnLeft = 0;
                  actor.__iceWolfV072StairBound = true;
                  actor.__iceWolfV072BoundLeft = 6;
                  actor.__iceWolfV072StairPace = 'rescue';
                  actor.__iceWolfV072StairTarget = { x: ax + rescueHop.vx * rescueHop.distance, y: ay + rescueHop.vy * rescueHop.distance };
                  goalX = actor.__iceWolfV072StairTarget.x;
                  goalY = actor.__iceWolfV072StairTarget.y;
                }
              }
            } else if (rescueTargetDist <= rescueDistance) {
              const targetVars = rescueTarget.getVariables();
              const targetState = targetVars.get('State').getAsString();
              if (targetState === 'FrozenWolfCandidate') {
                targetVars.get('Role').setString('Wolf');
                targetVars.get('State').setString('Active');
                targetVars.get('AIWolfModeLeft').setNumber(0);
                targetVars.get('AIWolfCooldownLeft').setNumber(1.5);
                actorVars.get('State').setString('Frozen');
              } else if (targetState === 'Frozen') {
                targetVars.get('State').setString('Active');
                actor.__iceWolfAIRescueCooldown = 1.0;
                rescueTarget.__iceWolfAIRescueCooldown = 1.2;
                if (rescueTarget === player && vars.get('CpuWolfDiagPhase').getAsNumber() === 2) {
                  vars.get('CpuWolfDiagPhase').setNumber(3);
                }
              }
              continue;
            }
            const safeRescueDist = Math.max(rescueTargetDist, 1);
            vx = (tx - ax) / safeRescueDist;
            vy = (ty - ay) / safeRescueDist;
            goalX = tx;
            goalY = ty;
            speed = rescueSpeed;
            hasIntent = true;
            actor.__iceWolfAITurnLeft = 0;
          }
        }
      }
      // v0.7.0: after fleeing and rescuing, a Human CPU works the nearest live switch
      // (and rides the stairs when it is on the other floor).
      // v0.7.2: that ride is gated on the per-Human delay and the two-rider limit, so
      // the group spreads out instead of queueing at the pads.
      if (!hasIntent && typeof runtimeScene.__iceWolfV070SwitchIntent === 'function') {
        const switchIntent = runtimeScene.__iceWolfV070SwitchIntent(actor, ax, ay, dt);
        const switchFloor = actor.__iceWolfV070SwitchTargetFloor || humanFloor;
        const crossingForSwitch = switchFloor !== humanFloor;
        if (switchIntent && (!crossingForSwitch || aiCanCross(actor))) {
          vx = switchIntent.vx;
          vy = switchIntent.vy;
          speed = switchIntent.speed;
          hasIntent = true;
          goalX = switchIntent.tx;
          goalY = switchIntent.ty;
          actor.__iceWolfAITurnLeft = 0;
          if (crossingForSwitch) {
            actor.__iceWolfV072StairBound = true;
            actor.__iceWolfV072BoundLeft = 6;
            actor.__iceWolfV072StairPace = 'rescue';
            const padHop = aiStairToward(actor, switchFloor === '2F' ? 1608.5 : -8);
            if (padHop) actor.__iceWolfV072StairTarget = { x: ax + padHop.vx * padHop.distance, y: ay + padHop.vy * padHop.distance };
          }
        }
      }
      if (!hasIntent) {
        if (!Number.isFinite(actor.__iceWolfAITurnLeft) || actor.__iceWolfAITurnLeft <= 0 || !Number.isFinite(actor.__iceWolfAIDirX) || !Number.isFinite(actor.__iceWolfAIDirY)) {
          const angle = Math.random() * Math.PI * 2;
          actor.__iceWolfAIDirX = Math.cos(angle);
          actor.__iceWolfAIDirY = Math.sin(angle);
          actor.__iceWolfAITurnLeft = 0.65 + Math.random() * 0.9;
        }
        actor.__iceWolfAITurnLeft -= dt;
        vx = actor.__iceWolfAIDirX;
        vy = actor.__iceWolfAIDirY;
        goalX = ax + vx * 220;
        goalY = ay + vy * 220;
      }
      if ((actor.__iceWolfV068SpeedBoostLeft || 0) > 0) speed *= 1.35;
      // v0.7.4: the same path and steering as the Wolf, so a Human walks to the
      // doorway, the switch and the frozen ally instead of pressing into a wall.
      if (speed > 0) {
        const steered = aiSteer(actor, vx, vy, speed, goalX, goalY);
        vx = steered.x;
        vy = steered.y;
      }
      const humanNextX = actor.getX() + vx * speed * dt;
      const humanNextY = actor.getY() + vy * speed * dt;
      const humanOnSecondFloor = (actor.getX() + actor.getWidth() / 2) > 792;
      actor.setX(Math.max(humanOnSecondFloor ? 892 : -708, Math.min(humanOnSecondFloor ? 2292 : 692, humanNextX)));
      actor.setY(Math.max(-708, Math.min(692, humanNextY)));
    }
  }
}

