 * crowded (Build 7 -> Build 8: warp/stair/speed 110 -> 84, gate 96 -> 72,
 * switch 84 -> 64 = 72-76%). The reach follows the plate it belongs to:
 * SWITCH_RANGE for the player and AI_SWITCH_HOLD_RANGE for a CPU, so nothing
 * that could be reached before is out of reach now. */
const SWITCH_SIZE = 64;

const AI_SWITCH_HOLD_RANGE = 28;   // Build 8: a CPU stands on the 64px plate
                                   // (34 inside the old 84px one)
const SWITCH_HOLD = 1.6;

