// ---------------------------------------------------------------- C. nobody freezes in place during normal play
harness.setSceneVariable('RoundCommand', 'TestStartWolf');
await harness.stepFrames(5);
harness.setSceneVariable('GameOver', false);
harness.setSceneVariable('SwitchEscapeEnabled', true);
const crowd = harness.getObjects('Actor');
for (const actor of crowd) {
  harness.setObjectVariable(actor.id, 'Role', 'Human');
  harness.setObjectVariable(actor.id, 'State', 'Active');
  harness.setObjectVariable(actor.id, 'AIWolfModeLeft', 0);
  harness.setObjectVariable(actor.id, 'AIWolfCooldownLeft', 999);
  harness.setObjectPosition(actor.id, -400 + 160 * crowd.indexOf(actor), -300 + 120 * (crowd.indexOf(actor) % 3));
}
const walker = harness.getObjects('Player')[0];
harness.setObjectVariable(walker.id, 'Role', 'Human');
harness.setObjectVariable(walker.id, 'State', 'Disabled');
let previous = {};
let stillFrames = {};
let longestStill = {};
for (const actor of crowd) {
  const now = actorAt(actor.id);
  previous[actor.id] = { x: now.centerX, y: now.centerY };
  stillFrames[actor.id] = 0;
  longestStill[actor.id] = 0;
}
for (let sample = 0; sample < 60; sample += 1) {
  await harness.stepFrames(10);
  for (const actor of crowd) {
    const now = actorAt(actor.id);
    const moved = Math.hypot(now.centerX - previous[actor.id].x, now.centerY - previous[actor.id].y);
    if (moved < 1.5) stillFrames[actor.id] += 10;
    else stillFrames[actor.id] = 0;
    longestStill[actor.id] = Math.max(longestStill[actor.id], stillFrames[actor.id]);
    previous[actor.id] = { x: now.centerX, y: now.centerY };
  }
}
for (const actor of crowd) {
  harness.assert(longestStill[actor.id] < 150, `Actor ${objVar(actor.id, 'DisplayId')} never locked up: ${longestStill[actor.id]} frames`);
}
harness.assert(num('AiSteerUnstickCount') >= 0, `unstick counter published: ${num('AiSteerUnstickCount')}`);
harness.assert(harness.getObjects('BuildText')[0].text === 'ICE WOLF v1.0.0', `build marker: ${harness.getObjects('BuildText')[0].text}`);

/* v1.0.0 — the 12-language shipping check, run through the game's own harness.
 *
 * It proves four things:
 *   1. the table holds every line in all twelve languages (nothing missing and
 *      no Japanese kana left inside a translation),
 *   2. the language can be switched from SETTINGS at any time and the HUD, the
 *      notification banner and the action labels follow it,
 *   3. switching back to Japanese gives the Japanese lines back (the events keep
 *      writing Japanese, so nothing is lost),
 *   4. the build reads `ICE WOLF v1.0.0` in every language.
 */
const num = (name) => harness.getSceneVariable(name)?.value ?? -1;
const str = (name) => harness.getSceneVariable(name)?.value ?? '';
const flag = (name) => harness.getSceneVariable(name)?.value === true;
const text = (name) => (harness.getObjects(name)[0]?.text) || '';
const KANA = /[\u3040-\u30fa\u30fc-\u30ff]/;
const LANGS = ['ja', 'en', 'zh-Hans', 'zh-Hant', 'ko', 'es', 'fr', 'de', 'pt', 'it', 'hi', 'id'];
const EXPECT = {
  ja: { role: 'あなた：人狼', count: '生存: 6 / 凍結: 0', switchText: 'スイッチ: 0/3', infect: '[ 人狼役にする ]' },
  en: { role: 'You: Wolf', count: 'Alive: 6 / Frozen: 0', switchText: 'Switches: 0/3', infect: '[ MAKE A WOLF ]' },
  ko: { role: '나: 늑대', count: '생존: 6 / 빙결: 0', switchText: '스위치: 0/3', infect: '[ 늑대로 지정 ]' },
  es: { role: 'Tú: Lobo', count: 'Vivos: 6 / Congelados: 0', switchText: 'Interruptores: 0/3', infect: '[ HACER LOBO ]' }
};
const setLanguage = async (code) => {
  harness.setSceneVariable('LanguageCommand', code);
  await harness.stepFrames(2);
};
const startWolfRound = async () => {
  harness.setSceneVariable('RolePreference', 'Wolf');
  harness.setSceneVariable('RoundCommand', 'TestStartWolf');
  await harness.stepFrames(5);
};

await harness.goToScene('FROST LAB');
await harness.stepFrames(3);

// 1. the table itself
harness.assert(num('LanguageCount') === 12, `twelve languages are shipped: ${num('LanguageCount')}`);
harness.assert(str('LanguageList') === LANGS.join(','), `the language list is exact: ${str('LanguageList')}`);
harness.assert(num('LanguageKeys') >= 100, `the table carries the whole UI: ${num('LanguageKeys')} keys`);
harness.assert(num('LanguageMissing') === 0, `every key has all twelve languages (missing: ${num('LanguageMissing')})`);
harness.assert(num('LanguageLeaks') === 0, 'no Japanese kana is left inside another language');
harness.assert(flag('I18nReady'), 'the language layer is up');
harness.assert(LANGS.indexOf(str('LanguageCode')) >= 0, `the start language is one of the twelve: ${str('LanguageCode')}`);

// 2. every language, on a live round
for (const code of LANGS) {
  await setLanguage(code);
  harness.assert(str('LanguageCode') === code, `SETTINGS switches to ${code}: ${str('LanguageCode')}`);
  await startWolfRound();
  harness.assert(text('BuildText') === 'ICE WOLF v1.0.0', `${code}: the build reads ICE WOLF v1.0.0: ${text('BuildText')}`);
  harness.assert(text('RoleText').length > 0, `${code}: the role line is shown`);
  harness.assert(text('CountText').indexOf('6') >= 0, `${code}: the survivor counter keeps its numbers: ${text('CountText')}`);
  harness.assert(text('SwitchText').indexOf('0/3') >= 0 || text('SwitchText').indexOf('0 / 3') >= 0, `${code}: the switch HUD keeps its count: ${text('SwitchText')}`);
  if (code !== 'ja') {
    harness.assert(!KANA.test(text('RoleText')), `${code}: the role line is not Japanese: ${text('RoleText')}`);
    harness.assert(!KANA.test(text('CountText')), `${code}: the counter is not Japanese: ${text('CountText')}`);
    harness.assert(text('RoleText') !== EXPECT.ja.role, `${code}: the role line changed with the language`);
    harness.assert(num('LanguageHudTranslated') >= 3, `${code}: the HUD pass translated ${num('LanguageHudTranslated')} lines`);
  } else {
    harness.assert(num('LanguageHudTranslated') === 0, 'Japanese writes the source lines untouched');
  }
  if (EXPECT[code]) {
    harness.assert(text('RoleText') === EXPECT[code].role, `${code}: role line "${text('RoleText')}"`);
    harness.assert(text('CountText') === EXPECT[code].count, `${code}: counter "${text('CountText')}"`);
    harness.assert(text('SwitchText') === EXPECT[code].switchText, `${code}: switch HUD "${text('SwitchText')}"`);
  }
  harness.setSceneVariable('RoundCommand', 'Menu');
  await harness.stepFrames(2);
}

// 3. the wording the player actually sees mid-round, then back to Japanese
await setLanguage('en');
await startWolfRound();
harness.assert(text('RoleText') === 'You: Wolf', `the role line in English: ${text('RoleText')}`);
harness.assert(text('InfectButton') === '[ MAKE A WOLF ]', `the wolf-target button in English: ${text('InfectButton')}`);
harness.assert(text('StatusText').indexOf('Wolf Mode') >= 0, `the wolf status in English: ${text('StatusText')}`);
// the notification banner: step on a speed floor and read what it says
const speedPad = harness.getObjects('SpeedPad')[0];
const playerId = harness.getObjects('Player')[0].id;
if (speedPad) harness.setObjectPosition(playerId, speedPad.centerX - 8, speedPad.centerY - 8);
await harness.stepFrames(3);
harness.assert(text('ActionFeedbackText').indexOf('Speed up') >= 0,
  `the banner speaks English: ${text('ActionFeedbackText')}`);

const actors = harness.getObjects('Actor');
for (const actor of actors) harness.setObjectVariable(actor.id, 'State', 'Frozen');
await harness.stepFrames(6);
harness.assert(text('WinText').indexOf('WOLVES WIN') >= 0, `the win banner in English: ${text('WinText')}`);
harness.assert(text('ActionFeedbackText').indexOf('Everyone frozen') >= 0, `the all-frozen banner in English: ${text('ActionFeedbackText')}`);
harness.assert(num('LanguageHudTranslated') >= 3, 'the translated HUD lines are counted');

await setLanguage('ja');
harness.assert(text('WinText') === '人狼の勝利', `Japanese comes back at once: ${text('WinText')}`);
harness.assert(text('RoleText') === 'あなた：人狼', `the Japanese role line returns: ${text('RoleText')}`);
harness.assert(num('LanguageHudTranslated') === 0, 'Japanese shows the source lines');
harness.assert(text('BuildText') === 'ICE WOLF v1.0.0', 'the build line does not depend on the language');

const num = (name) => harness.getSceneVariable(name)?.value ?? -1;
const str = (name) => harness.getSceneVariable(name)?.value ?? '';
const dist = (a, b) => Math.hypot(a.centerX - b.centerX, a.centerY - b.centerY);
const round = (value) => Math.round(value);
await harness.goToScene('FROST LAB');
harness.setSceneVariable('LanguageCommand', 'ja');
harness.setSceneVariable('RoundCommand', 'TestStartWolf');
await harness.stepFrames(5);

/* 1. The five gimmicks are all there, one size down (Build 8 = 72-76% of Build 7). */
const warps = harness.getObjects('WarpPad');
const stairs = harness.getObjects('StairPad');
const speeds = harness.getObjects('SpeedPad');
const switches = harness.getObjects('SwitchPad');
const gates = harness.getObjects('GatePad');
harness.assert(warps.length === 2 && stairs.length === 4 && speeds.length === 2 && switches.length === 5 && gates.length === 3,
  `the five gimmicks are all here: warp ${warps.length}, stair ${stairs.length}, speed ${speeds.length}, switch ${switches.length}, gate ${gates.length}`);
for (const pad of warps.concat(stairs, speeds)) {
  harness.assert(pad.width === 84 && pad.height === 84, `warp, stair and speed plate is 84x84: ${pad.width}x${pad.height}`);
}
for (const pad of switches) {
  harness.assert(pad.width === 64 && pad.height === 64, `switch plate is 64x64: ${pad.width}x${pad.height}`);
}
for (const pad of gates) {
  harness.assert(pad.width === 72 && pad.height === 72, `gate plate is 72x72: ${pad.width}x${pad.height}`);
}
harness.assert(num('WarpPadSize') === 84 && num('StairPadSize') === 84 && num('SpeedPadSize') === 84,
  `warp/stair/speed size is published: ${num('WarpPadSize')}/${num('StairPadSize')}/${num('SpeedPadSize')}`);
harness.assert(num('SwitchPadSize') === 64 && num('GatePadSize') === 72,
  `switch/gate size is published: ${num('SwitchPadSize')}/${num('GatePadSize')}`);
harness.assert(num('SwitchHoldRange') === 76 && num('AiSwitchHoldRange') === 28,
  `hold reach follows the plates: player ${num('SwitchHoldRange')}, CPU ${num('AiSwitchHoldRange')}`);

/* 2. Nothing the player walks over is inside or against a wall. */
const walls = harness.getObjects('Wall');
const overlaps = (a, b, margin) => (a.x - margin < b.x + b.width && a.x + a.width + margin > b.x
  && a.y - margin < b.y + b.height && a.y + a.height + margin > b.y);
const all = warps.concat(stairs, speeds, switches, gates);
const wallHits = [];
let floorHits = 0;
for (const pad of all) {
  for (const wall of walls) if (overlaps(pad, wall, 8)) wallHits.push(`${round(pad.centerX)},${round(pad.centerY)}`);
  if ((pad.centerX > 792 && (pad.x < 886 || pad.x + pad.width > 2298)) || (pad.centerX <= 792 && (pad.x < -714 || pad.x + pad.width > 698))) floorHits += 1;
  if (pad.y < -714 || pad.y + pad.height > 698) floorHits += 1;
}
harness.assert(wallHits.length === 0, `no gimmick touches a wall: ${wallHits.slice(0, 4)}`);
harness.assert(floorHits === 0, `every gimmick stays on its own floor: ${floorHits}`);

/* 3. The complaint from the walk: the warp no longer crowds the stairs. */
for (const warp of warps) {
  let nearest = Infinity;
  for (const stair of stairs) nearest = Math.min(nearest, dist(warp, stair));
  harness.assert(nearest >= 300, `a warp plate is at least 300px from every stair plate: ${round(nearest)}px`);
}
harness.assert(dist(warps[0], warps[1]) >= 800, `the warp pair still crosses the lab: ${round(dist(warps[0], warps[1]))}px`);

/* 4. The smaller plates still do their job for the player. */
const player = harness.getObjects('Player')[0];
harness.setObjectVariable(player.id, 'Role', 'Human');
harness.setObjectVariable(player.id, 'State', 'Active');
harness.setSceneVariable('GameOver', false);
for (const actor of harness.getObjects('Actor')) harness.setObjectVariable(actor.id, 'State', 'Disabled');
harness.setObjectPosition(player.id, warps[0].centerX - 8.5, warps[0].centerY - 8.5);
await harness.stepFrames(3);
harness.assert(num('WarpCount') === 1, `stepping on the smaller warp still teleports: ${num('WarpCount')}`);
const landed = harness.getObjects('Player')[0];
harness.assert(dist(landed, warps[1]) < 30, `the warp lands on its partner plate: ${round(dist(landed, warps[1]))}px`);
const speed = speeds[0];
harness.setObjectPosition(player.id, speed.centerX - 8.5, speed.centerY - 8.5);
await harness.stepFrames(3);
harness.assert(num('SpeedPadTriggers') >= 1, `the smaller speed floor still boosts: ${num('SpeedPadTriggers')}`);
harness.setSceneVariable('StairCooldownLeft', 0);
harness.setObjectVariable(player.id, 'State', 'Active');
harness.setObjectPosition(player.id, stairs[0].x + 6, stairs[0].y + 6);
await harness.stepFrames(4);
harness.assert(str('PlayerFloor') === '2F', `the smaller stair still carries the player up: ${str('PlayerFloor')}`);
harness.assert(num('StairRideCount') === 1, `one stair ride is counted: ${num('StairRideCount')}`);

/* 5. The hold reach is the smaller one: 70px works, 88px does not. */
harness.setSceneVariable('SwitchEscapeEnabled', true);
const entries = String(str('SwitchLayout')).split(';').filter(Boolean);
const liveIndex = entries.findIndex((entry) => {
  const parts = entry.split(':');
  return parts[3] === 'correct' && parts[4] === '0';
});
harness.assert(liveIndex >= 0, `a correct switch is still waiting: ${liveIndex}`);
const livePad = switches[liveIndex];
harness.setObjectPosition(player.id, livePad.centerX - 8.5, livePad.centerY - 78.5);
await harness.stepFrames(3);
harness.assert(num('SwitchHoldIndex') === liveIndex, `70px from the plate is inside the hold reach: ${num('SwitchHoldIndex')}`);
harness.setObjectPosition(player.id, livePad.centerX - 8.5, livePad.centerY - 96.5);
await harness.stepFrames(3);
harness.assert(num('SwitchHoldIndex') === -1, `88px from the plate is outside the hold reach: ${num('SwitchHoldIndex')}`);
harness.assert(harness.getSceneVariable('SwitchHoldVisible')?.value === false, 'no ring where there is no switch');

/* 6. A CPU still works a switch with the shorter approach distance. */
const worker = harness.getObjects('Actor')[0];
harness.setObjectVariable(worker.id, 'Role', 'Human');
harness.setObjectVariable(worker.id, 'State', 'Active');
harness.setObjectPosition(worker.id, livePad.centerX - 8.5, livePad.centerY - 8.5);
await harness.stepFrames(120);
harness.assert(num('SwitchTriggeredCount') >= 1, `a CPU holds the smaller switch at 28px: ${num('SwitchTriggeredCount')}`);
harness.assert(num('SwitchActiveCount') + num('SwitchDummyTriggered') + num('SwitchTrapTriggered') >= 1,
  `the CPU press counted somewhere: ${num('SwitchActiveCount')}/${num('SwitchDummyTriggered')}/${num('SwitchTrapTriggered')}`);
